-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 6,
        gaps_out = 16,

        border_size = 3,

        -- border colours come from rice.lua (see bottom of LOOK AND FEEL)

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "scrolling",   -- windows sit in a row of columns; scroll right for more
    },

    decoration = {
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 0.93,

        shadow = {
            enabled      = true,
            range        = 14,
            render_power = 3,
        },

        blur = {
            enabled   = true,
            size      = 6,
            passes    = 2,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })

-- Smooth layer curves (Material "emphasized"): long gentle settle in, quick clean exit
hl.curve("emphasizedDecel", { type = "bezier", points = { {0.05, 0.7},  {0.1, 1}     } })
hl.curve("emphasizedAccel", { type = "bezier", points = { {0.3, 0},     {0.8, 0.15}  } })
hl.curve("softFade",        { type = "bezier", points = { {0.2, 0},     {0, 1}       } })

-- Default springs
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

-- Theme colours / rounding, generated by the `rice` switcher (~/.config/rice)
dofile(os.getenv("HOME") .. "/.config/hypr/rice.lua")

hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
-- windows: short ease-out curves instead of springs, so opening several at once (and the
-- re-tiling it causes) settles fast instead of stacking up long springy moves
hl.animation({ leaf = "windows",       enabled = true,  speed = 1.5,  bezier = "easeOutQuint" })
-- moving windows (panning the infinite desktop, scrolling the row) glides on a spring, so it keeps some weight
hl.animation({ leaf = "windowsMove",   enabled = true,  speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 3,    bezier = "emphasizedDecel", style = "slide bottom" })  -- new windows rise from the bottom
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 0.8,  bezier = "linear",       style = "popin 95%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 0.8,  bezier = "quick" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 0.8,  bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 5,    bezier = "emphasizedDecel", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 2.6,  bezier = "emphasizedAccel", style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 4,    bezier = "softFade" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 2.6,  bezier = "emphasizedAccel" })
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 1.21, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

