-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Float nmtui (opened from waybar network module)
hl.window_rule({
    name   = "float-nmtui",
    match  = { class = "^nmtui$" },
    float  = true,
    size   = "720 520",
    center = true,
})

-- MacShell's System Settings: a floating window in the middle, like on a Mac
hl.window_rule({
    name   = "float-macshell-settings",
    match  = { title = "^System Settings$" },
    float  = true,
    size   = "880 620",
    center = true,
})

-- Float Larry's settings window (right-click his tab, or hyprland-pets --settings)
hl.window_rule({
    name   = "float-larry-settings",
    match  = { class = "^larry$" },
    float  = true,
    center = true,
})

-- The Quickshell rice (ekitai-qs) animates its own bar, panels and popups
hl.layer_rule({
    name    = "ekitai-shell-no-anim",
    match   = { namespace = "^ekitai-" },
    no_anim = true,
})

-- The Quickshell rice's glass look: frost what's behind the bar, panels, widgets and popups. Only takes
-- effect while blur is on, which the glass look switches (Look.qml); not the wallpaper layer itself
hl.layer_rule({
    name         = "ekitai-glass",
    match        = { namespace = "^ekitai-(bar|panel|launcher|osd|toasts|desktop|picker)$" },
    blur         = true,
    ignore_alpha = 0.3,
})

-- PureShell (the pure rice) animates its own island, bar and panels, and frosts what's behind them
hl.layer_rule({
    name    = "pure-shell-no-anim",
    match   = { namespace = "^pure-" },
    no_anim = true,
})
hl.layer_rule({
    name         = "pure-frost",
    match        = { namespace = "^pure-(island|bar|panel|launcher|toasts)$" },
    blur         = true,
    ignore_alpha = 0.2,
})

-- MacShell (the mac rice) animates its own menus and panels; frost behind the menu bar, dock, menus and panels
hl.layer_rule({
    name    = "mac-shell-no-anim",
    match   = { namespace = "^mac-" },
    no_anim = true,
})
hl.layer_rule({
    name         = "mac-frost",
    match        = { namespace = "^mac-(bar|dock|menu|panel|spotlight|banners)$" },
    blur         = true,
    ignore_alpha = 0.05,
})

-- NostalgiaShell (the nostalgia rice) animates its own bar, dock and panels; frost behind the Home Menu and panels
hl.layer_rule({
    name    = "nostalgia-shell-no-anim",
    match   = { namespace = "^nostalgia-" },
    no_anim = true,
})
hl.layer_rule({
    name         = "nostalgia-glass",
    match        = { namespace = "^nostalgia-(bar|dock|island|side)$" },  -- the bar's, dock's and island's smoked glass
    blur         = true,
    ignore_alpha = 0.25,
})
hl.layer_rule({
    name         = "nostalgia-desk-frost",
    match        = { namespace = "^nostalgia-desk$" },   -- the desktop grid's tiles: frosted over a busy wallpaper
    blur         = true,
    ignore_alpha = 0.3,                                  -- (not the faint cursor glow round them)
})
hl.layer_rule({
    name         = "nostalgia-frost",
    match        = { namespace = "^nostalgia-(power)$" },  -- not the Home Menu: blurring the whole screen behind it lagged
    blur         = true,
    ignore_alpha = 0.1,
})

-- Bloom (the bloom rice) animates its own island, panels and widgets
hl.layer_rule({
    name    = "bloom-shell-no-anim",
    match   = { namespace = "^bloom-" },
    no_anim = true,
})

-- The shell switcher (SUPER + ALT + S, ~/.config/quickshell/switcher) fades itself; frost behind its cards
hl.layer_rule({
    name    = "rice-switcher",
    match   = { namespace = "^rice-switcher$" },
    no_anim = true,
    blur    = true,
    ignore_alpha = 0.1,
})

-- Blur behind waybar
hl.layer_rule({
    name         = "blur-waybar",
    match        = { namespace = "^waybar$" },
    blur         = true,
    animation    = "slide top",  -- drops in from the top edge on SUPER+Tab
    ignore_alpha = 0.2,
})

